// pwa_assets.js — manifeste, service worker, icônes et image sociale (OG).
export const PWA_MANIFEST = `{"name": "7 MOTION", "short_name": "7 MOTION", "description": "L'exp\u00e9rience t\u00e9l\u00e9, sereine et premium.", "start_url": "/?app=1", "scope": "/", "display": "standalone", "orientation": "portrait", "background_color": "#0c0c0e", "theme_color": "#0c0c0e", "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"}, {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png"}]}`;
export const PWA_SW = `const CACHE = 'sevenmotion-v1';
self.addEventListener('install', function(e){ self.skipWaiting(); });
self.addEventListener('activate', function(e){ e.waitUntil(self.clients.claim()); });
self.addEventListener('fetch', function(e){
  var req = e.request;
  if (req.method !== 'GET') return;
  // Network-first sur la navigation : toujours frais en ligne, repli cache hors-ligne.
  if (req.mode === 'navigate') {
    e.respondWith(
      fetch(req).then(function(r){ var c = r.clone(); caches.open(CACHE).then(function(x){ x.put(req, c); }); return r; })
      .catch(function(){ return caches.match(req).then(function(m){ return m || caches.match('/'); }); })
    );
  }
});
`;
